    "roseman-bsn": {"prerequisites":[{"course":"Physical/Biological Science, 16 credits, including 12 credits of anatomy, physiology and microbiology with labs","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Social Science, 6 credits","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Math: Statistics, 3 credits","code":null,"category":"stats","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"English college composition, 6 credits","code":null,"category":"eng1","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Humanities, 6 credits","code":null,"category":"humanities","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"Electives, 9 credits (not remedial, occupational, or recreational)","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null},{"course":"US and/or Nevada Constitution, 3 credits","code":null,"category":"other","min_grade":"C","within_years":"not_published","by_when":"see_text","one_of":null}],"rules":{"gpa_overall_min":2.75,"gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":{"name":"TEAS","min_overall":58.7,"min_sections":"not_published","max_attempts":3,"valid_months":12},"selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"49 semester credits; courses completed with a grade of \"C\" (2.0) or higher. Physical/Biological Science 16 (must include 12 anatomy, physiology, and microbiology with labs credits); Social Science 6; Math 3 (Statistics); English 6 (college composition); Humanities 6; Electives 9; US and/or Nevada Constitution 3. Apply page: \"will accept applications with coursework in progress\"; credit-by-examination science courses not accepted.","gpa":"Minimum cumulative GPA 2.75.","exam":"ATI TEAS minimum overall score 58.7% (minimums may change each academic year); score dated within the 12 months before the application date; no more than 3 times in a calendar year, at least 4 weeks between tests.","selection":"Initial eligibility on prerequisite grades and TEAS; competitive review for interview; interview and writing sample required; final selection scored on academic achievement, interview, TEAS and writing sample. Meeting minimums does not guarantee admission. Rolling admissions; classes may fill before the deadline.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://www.roseman.edu/academic-programs/college-of-nursing/accelerated-bachelor-of-science-in-nursing/","https://www.roseman.edu/academic-programs/college-of-nursing/accelerated-bachelor-of-science-in-nursing/apply/"],"last_verified":"2026-11-26","academic_year":"Summer 2027 / Fall 2027 admission","deadline":"Rolling (classes may fill early). Summer 2027 hybrid-online: closes Mar 26, 2027; On-campus cohort: Aug 7, 2026 - May 28, 2027 (program page says Fall 2027, apply page says Summer 2027); Fall 2027 hybrid-online: Apr 1 - Jul 30, 2027; Spring 2028 hybrid-online: Jul 1 - Nov 1, 2027. Spring 2027 hybrid closed Nov 1, 2026.","notes":"Apply via NursingCAS; $250 non-refundable seating deposit within 14 days of offer. Interview and writing sample required; official transcripts (dated within 12 months) must arrive before an interview is scheduled. Background check and SSN required. No transfer of nursing coursework. TOEFL if lacking 6 credits English composition or 4 semesters at a US institution. Pages do not state a prior-degree requirement; 49 prerequisite credits. Campus (Henderson NV or South Jordan UT) assigned with offer."},
    "roseman-fnp": {"prerequisites":[{"course":"Undergraduate statistics","code":null,"category":"stats","min_grade":"B","within_years":10,"by_when":"not_published","one_of":null}],"rules":{"gpa_overall_min":"see_text","gpa_prereq_min":"not_published","gpa_science_min":"not_published","exam":"none","selection":"competitive","points":"not_applicable","retakes":"not_published","local_priority":"not_published","seats":"not_published"},"wording":{"prerequisites":"Undergraduate statistics course (completed within 10 years of applying to the program) with a \"B\" or better.","gpa":"Minimum GPA of 3.0 Cumulative in Nursing undergraduate coursework.","exam":"Requirements list no GRE or entrance exam; only TOEFL and foreign transcript evaluation if applicable.","selection":"Personal interview with the interview committee (by invitation). Meeting the minimum application requirements is not a guarantee for admission.","points":null,"retakes":null,"local_priority":null,"seats":null},"source_urls":["https://www.roseman.edu/academic-programs/college-of-nursing/msnfnp-dnpfnp/"],"last_verified":"2026-11-26","academic_year":"July 2027 start","deadline":"not_published","notes":"GPA is 3.0 on undergraduate nursing coursework (not overall cumulative), hence see_text. BSN from ACEN/CCNE/CNEA-accredited program; unencumbered RN license or eligibility in the state of clinicals; one year RN experience preferred; two Likert-scale recommendation letters; apply via NursingCAS; $500 seating deposit. Page lists 2025-2026 tuition $60,400 ($35,400 MSN, $25,000 DNP). Next start July 2027; no application deadline published."},
